const body = pm.response.json();
const base = pm.environment.get("baseCurrency");
const targets = pm.environment
    .get("targetCurrencies")
    .split(",")
    .map(c => c.trim());
const maxTime = Number(
    pm.environment.get("maxResponseTime")
);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response time is within configured limit", function () {
    pm.expect(pm.response.responseTime).to.be.below(maxTime);
});

pm.test("Response result is success", function () {
    pm.expect(body.result).to.eql("success");
});

pm.test("Base currency matches environment", function () {
    pm.expect(body.base_code).to.eql(base);
});

pm.test("Rates object exists", function () {
    pm.expect(body.rates).to.be.an("object");
});

pm.test("Target currencies have positive numeric rates", function () {
    targets.forEach(function (currency) {
        pm.expect(body.rates).to.have.property(currency);
        pm.expect(body.rates[currency]).to.be.a("number");
        pm.expect(body.rates[currency]).to.be.above(0);
    });
});

pm.test("Base currency rate equals 1", function () {
    pm.expect(body.rates[base]).to.eql(1);
});


if (body.rates && typeof body.rates.SAR === "number") {
    pm.environment.set("capturedSarRate", body.rates.SAR);
}

pm.test("Captured SAR rate is valid", function () {
    const rate = Number(pm.environment.get("capturedSarRate"));
    pm.expect(rate).to.be.a("number");
    pm.expect(rate).to.be.above(0);
});

pm.test("Requested base currency matches response", function () {
    const requestedBase = pm.environment.get("baseCurrency");
    const responseBody = pm.response.json();

    pm.expect(responseBody.base_code).to.eql(requestedBase);
});
